import json
d = json.load(open('/private/tmp/claude-501/-Users-taha/c7a33960-1c96-4b0c-b15f-02a996414e54/scratchpad/apple_page.json'))
pcs = d['primaryContentSections']
def dump(node, depth=0):
    if isinstance(node, dict):
        t = node.get('type')
        if t == 'text':
            print(node.get('text',''), end='')
        elif t == 'paragraph':
            for c in node.get('inlineContent', []):
                dump(c, depth+1)
            print()
        elif t == 'heading':
            print()
            print('#'*node.get('level',2), node.get('text',''))
        elif t == 'codeVoice':
            print(node.get('code',''), end='')
        elif t == 'reference':
            print(node.get('identifier',''), end='')
        elif 'content' in node:
            for c in node['content']:
                dump(c, depth+1)
        elif 'items' in node:
            for it in node['items']:
                print('-', end=' ')
                dump(it, depth+1)
    elif isinstance(node, list):
        for n in node:
            dump(n, depth)

for sec in pcs:
    dump(sec)
"
